1	/**
2	 * The composed Angular CLI era migration: workspace configuration, TypeScript
3	 * configuration, package manifest and application source, lifted onto one
4	 * declared target cell and reported as a single itemised changeset.
5	 *
6	 * The changeset is the product. It records, per file, the bytes before and
7	 * after as digests and the individual changes that produced them, and it
8	 * separates application files from workspace files so that a count of changed
9	 * application files means what it says: source the application owns, changed by
10	 * a transform, not a version number edited in a manifest.
11	 */
12	
13	import { createHash } from 'node:crypto';
14	import {
15		alignAngularPackageManifest,
16		compareStrings,
17		type AngularTargetCell,
18		type DependencyChange,
19	} from './angular-target-cell.ts';
20	import { migrateAngularSourceModule, type SourceChange } from './angular-source-migration.ts';
21	import {
22		migrateModalContentParams,
23		type ModalContentParamsChange,
24		type ModuleResolution,
25	} from './modal-content-params-migration.ts';
26	import { migrateNgrxEffectDecorators, type NgrxEffectChange } from './ngrx-effects-migration.ts';
27	import {
28		migratePackageStyleImports,
29		type PackageExportsReading,
30		type StyleImportChange,
31	} from './package-exports-style-imports.ts';
32	import { migrateSentryV8Tracing, type SentryV8Change } from './sentry-v8-migration.ts';
33	import {
34		declareUndeclaredRuntimeDependencies,
35		undeclaredRuntimeDependencies,
36		type InstalledPackage,
37	} from './undeclared-runtime-dependency.ts';
38	import {
39		migrateAngularTsConfig,
40		migrateAngularWorkspace,
41		normalizeFragmentPath,
42		type ConfigChange,
43	} from './angular-workspace-migration.ts';
44	import {
45		isAngularCliOneWorkspace,
46		synthesizeAngularWorkspace,
47		type SynthesizedWorkspace,
48	} from './angular-cli-json-workspace-synthesis.ts';
49	import { tslintConfigRemovals } from './tslint-toolchain-removal.ts';
50	import { declareBuilderPackages } from './builder-package-declaration.ts';
51	
52	export type WorkspaceFile = Readonly<{ path: string; source: string }>;
53	
54	export type AngularMigrationInput = Readonly<{
55		packageManifest: WorkspaceFile;
56		workspaceConfig: WorkspaceFile;
57		tsConfig: WorkspaceFile;
58		/** Application source modules, as read from the workspace. */
59		sourceModules: readonly WorkspaceFile[];
60		/**
61		 * Webpack fragments a wrapper builder reads, keyed by the path the workspace
62		 * writes for them. A fragment a target references but that is not supplied
63		 * here is reported unread and its wrapper builder is left in place.
64		 */
65		webpackFragments?: readonly WorkspaceFile[];
66		/**
67		 * Every workspace-relative path the tree carries, for capabilities that
68		 * decide a file should no longer exist. Only paths are needed: a file removed
69		 * because the toolchain that read it is gone does not have to be parsed. A
70		 * tree that supplies no list has no files removed.
71		 */
72		workspaceFiles?: readonly string[];
73		/**
74		 * Stylesheets the application owns, kept apart from {@link sourceModules}
75		 * because they are not modules: no source transform parses them, and the only
76		 * capability that reads them resolves package subpaths against an exports map.
77		 */
78		styleSheets?: readonly WorkspaceFile[];
79		/**
80		 * The published surface of packages whose stylesheet subpaths the application
81		 * imports, as read from the installed closure. A package not read here has its
82		 * style imports left exactly as they are.
83		 */
84		packageExports?: readonly PackageExportsReading[];
85		/**
86		 * The installed dependency closure, reduced to declarations and shipped
87		 * imports. Supplying it is what lets undeclared runtime dependencies be
88		 * detected; a tree that supplies none has none detected, which is a different
89		 * thing from having none.
90		 */
91		installedPackages?: readonly InstalledPackage[];
92		/** How the workspace resolves module specifiers written in its own source. */
93		moduleResolution?: ModuleResolution;
94	}>;
95	
96	export type MigratedFile = Readonly<{
97		path: string;
98		kind: 'application' | 'workspace';
99		changed: boolean;
100		sha256Before: string;
101		sha256After: string;
102		source: string;
103		changes: readonly string[];
104	}>;
105	
106	export type AngularMigration = Readonly<{
107		cell: string;
108		files: readonly MigratedFile[];
109		applicationFilesChanged: number;
110		workspaceFilesChanged: number;
111		applicationFilesScanned: number;
112		unhandled: readonly string[];
113		/**
114		 * Capabilities the migrated workspace deliberately no longer has, one line
115		 * per removal — a dropped lint target, a dropped configuration file, a
116		 * package the cell read and found no successor for. A reader is owed these by
117		 * name: they are the difference between the era workspace and this one that a
118		 * clean changeset would otherwise hide.
119		 */
120		declaredDifferences: readonly string[];
121		/** Files the migration decided the tree should no longer carry. */
122		removedFiles: readonly string[];
123	}>;
124	
125	function sha256(value: string): string {
126		return createHash('sha256').update(value).digest('hex');
127	}
128	
129	/**
130	 * Parse a workspace document only far enough to decide which format it is in.
131	 *
132	 * A document that is not JSON at all is handed on unparsed: the migration that
133	 * reads it next refuses it with the diagnosable error it already writes, and
134	 * duplicating that refusal here would report the same defect twice under two
135	 * different names.
136	 */
137	function safeParseJson(source: string): unknown {
138		try {
139			return JSON.parse(source) as unknown;
140		} catch {
141			return null;
142		}
143	}
144	
145	function describeConfigChange(change: ConfigChange): string {
146		if (change.to === null) return `removed ${change.path} (was ${change.from ?? 'absent'})`;
147		if (change.from === null) return `added ${change.path} = ${change.to}`;
148		return `${change.path}: ${change.from} -> ${change.to}`;
149	}
150	
151	function describeDependencyChange(change: DependencyChange): string {
152		const target = `${change.field}.${change.name}`;
153		return change.to === null
154			? `removed ${target} (was ${change.from}) — ${change.reason}`
155			: `${target}: ${change.from} -> ${change.to} — ${change.reason}`;
156	}
157	
158	function describeSourceChange(
159		change:
160			| SourceChange
161			| NgrxEffectChange
162			| SentryV8Change
163			| ModalContentParamsChange
164			| StyleImportChange,
165	): string {
166		return `line ${change.line}: ${change.kind} ${change.from} -> ${change.to}`;
167	}
168	
169	function file(
170		input: WorkspaceFile,
171		source: string,
172		kind: MigratedFile['kind'],
173		changes: readonly string[],
174	): MigratedFile {
175		return Object.freeze({
176			path: input.path,
177			kind,
178			changed: source !== input.source,
179			sha256Before: sha256(input.source),
180			sha256After: sha256(source),
181			source,
182			changes: Object.freeze([...changes]),
183		});
184	}
185	
186	/**
187	 * Apply every capability of the adapter to one workspace.
188	 *
189	 * Order matters in exactly one place: the workspace migration decides which
190	 * builder targets cannot be carried, and the packages those targets released
191	 * are what the manifest alignment then removes. Nothing else is ordered, and no
192	 * capability reads a file it was not handed.
193	 */
194	export function migrateAngularCliEraWorkspace(
195		input: AngularMigrationInput,
196		cell: AngularTargetCell,
197	): AngularMigration {
198		const unhandled: string[] = [];
199		const declaredDifferences: string[] = [];
200		const fragments: Record<string, string> = {};
201		for (const fragment of input.webpackFragments ?? [])
202			fragments[normalizeFragmentPath(fragment.path)] = fragment.source;
203		/**
204		 * A workspace in the pre-`angular.json` Angular CLI 1.x format is translated
205		 * into the modern one before anything else reads it. Every capability below
206		 * expects a `projects` map with `architect` targets, and the era document has
207		 * neither; synthesizing first is what lets the rest of the adapter run on a
208		 * CLI 1.x tree without one of them learning a second workspace format.
209		 */
210		let synthesis: SynthesizedWorkspace | null = null;
211		let workspaceConfigSource = input.workspaceConfig.source;
212		if (isAngularCliOneWorkspace(safeParseJson(input.workspaceConfig.source))) {
213			synthesis = synthesizeAngularWorkspace(
214				input.workspaceConfig.source,
215				cell,
216				input.workspaceConfig.path,
217			);
218			workspaceConfigSource = synthesis.config;
219			unhandled.push(...synthesis.unhandled);
220			declaredDifferences.push(...synthesis.declaredDifferences);
221		}
222		const workspace = migrateAngularWorkspace(workspaceConfigSource, cell, fragments);
223		unhandled.push(...workspace.unhandled);
224		declaredDifferences.push(...workspace.declaredDifferences);
225		const configRemovals = tslintConfigRemovals(input.workspaceFiles ?? [], cell);
226		declaredDifferences.push(...configRemovals.map((removal) => removal.reason));
227		for (const absorbed of workspace.absorbedFragments)
228			unhandled.push(
229				`${absorbed.path} was absorbed into the official builder and is no longer referenced by any ` +
230					`target; it was left in the tree rather than deleted. Absorbed capabilities: ` +
231					absorbed.capabilities.map((entry) => `${entry.kind} ${entry.detail}`).join(', '),
232			);
233		const manifest: unknown = JSON.parse(input.packageManifest.source);
234		if (typeof manifest !== 'object' || manifest === null || Array.isArray(manifest))
235			throw new Error('Angular migration: the package manifest is not a JSON object');
236		const aligned = alignAngularPackageManifest(
237			manifest as Readonly<Record<string, unknown>>,
238			cell,
239			workspace.removedPackages,
240		);
241		unhandled.push(...aligned.unhandled);
242		declaredDifferences.push(...aligned.declaredDifferences);
243		/**
244		 * Holes the closure carries are closed after the cell alignment, not before:
245		 * the cell decides which lines the workspace runs, and an undeclared edge is
246		 * declared at the line the cell read for it.
247		 */
248		const holes = undeclaredRuntimeDependencies(input.installedPackages ?? []);
249		const declared = declareUndeclaredRuntimeDependencies(aligned.manifest, holes, cell);
250		unhandled.push(...declared.unhandled);
251		declaredDifferences.push(...declared.declaredDifferences);
252		/**
253		 * The packages the migrated workspace's own targets name are declared last,
254		 * after every capability that decides which targets survive: a builder
255		 * declaration for a target the workspace migration removed would install a
256		 * toolchain nothing runs.
257		 */
258		const builders = declareBuilderPackages(declared.manifest, workspace.config, cell);
259		unhandled.push(...builders.unhandled);
260		const tsConfig = migrateAngularTsConfig(input.tsConfig.source, cell);
261		unhandled.push(...tsConfig.unhandled);
262		const files: MigratedFile[] = [
263			file(
264				input.packageManifest,
265				`${JSON.stringify(builders.manifest, null, 2)}\n`,
266				'workspace',
267				[
268					...aligned.changes.map(describeDependencyChange),
269					...declared.declarations.map(
270						(entry) =>
271							`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
272					),
273					...builders.declarations.map(
274						(entry) =>
275							`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
276					),
277				],
278			),
279			file(
280				synthesis === null
281					? input.workspaceConfig
282					: { path: synthesis.path, source: input.workspaceConfig.source },
283				workspace.config,
284				'workspace',
285				synthesis === null
286					? workspace.changes.map(describeConfigChange)
287					: [
288							`synthesized ${synthesis.path} from ${synthesis.replacedPath}, the pre-angular.json ` +
289								'Angular CLI 1.x workspace format; the digest recorded before is that file',
290							...synthesis.changes.map(describeConfigChange),
291							...workspace.changes.map(describeConfigChange),
292						],
293			),
294			file(
295				input.tsConfig,
296				tsConfig.config,
297				'workspace',
298				tsConfig.changes.map(describeConfigChange),
299			),
300		];
301		/**
302		 * Source capabilities run in sequence over each module, each one handed what
303		 * the last produced. They are independent — one rewrites module specifiers,
304		 * the next replaces a removed NgRx decorator — and a module is counted as
305		 * changed if any of them changed a byte of it.
306		 */
307		/**
308		 * One capability is not per-module and cannot be: rewriting a modal call site
309		 * without rewriting the content component it supplied is the silent failure
310		 * that capability exists to refuse. It runs over the whole tree first, and
311		 * what it produced is what the per-module capabilities then see.
312		 */
313		const modal = migrateModalContentParams(input.sourceModules, input.moduleResolution ?? {});
314		unhandled.push(...modal.unhandled);
315		const modalByPath = new Map(modal.files.map((entry) => [entry.path, entry]));
316		for (const module of [...input.sourceModules].sort((left, right) =>
317			compareStrings(left.path, right.path),
318		)) {
319			const modalFile = modalByPath.get(module.path);
320			const entrySource = modalFile?.source ?? module.source;
321			const migrated = migrateAngularSourceModule(module.path, entrySource);
322			const effects = migrateNgrxEffectDecorators(module.path, migrated.source);
323			const sentry = migrateSentryV8Tracing(module.path, effects.source);
324			unhandled.push(...migrated.unhandled, ...effects.unhandled, ...sentry.unhandled);
325			files.push(
326				file(module, sentry.source, 'application', [
327					...(modalFile?.changes ?? []).map(describeSourceChange),
328					...migrated.changes.map(describeSourceChange),
329					...effects.changes.map(describeSourceChange),
330					...sentry.changes.map(describeSourceChange),
331				]),
332			);
333		}
334		/**
335		 * Stylesheets are application files too, and a blocked package subpath is an
336		 * application file that no longer builds. Each is offered to every package
337		 * reading the caller supplied; a stylesheet no reading touches is carried
338		 * through unchanged and still counted, so the scanned total means what it says.
339		 */
340		for (const sheet of [...(input.styleSheets ?? [])].sort((left, right) =>
341			compareStrings(left.path, right.path),
342		)) {
343			let source = sheet.source;
344			const changes: string[] = [];
345			for (const reading of input.packageExports ?? []) {
346				const styles = migratePackageStyleImports(sheet.path, source, reading);
347				unhandled.push(...styles.unhandled);
348				declaredDifferences.push(...styles.declaredDifferences);
349				changes.push(...styles.changes.map(describeSourceChange));
350				source = styles.source;
351			}
352			files.push(file(sheet, source, 'application', changes));
353		}
354		const applicationFiles = files.filter((entry) => entry.kind === 'application');
355		return Object.freeze({
356			cell: cell.id,
357			files: Object.freeze(files),
358			applicationFilesChanged: applicationFiles.filter((entry) => entry.changed).length,
359			workspaceFilesChanged: files.filter((entry) => entry.kind === 'workspace' && entry.changed)
360				.length,
361			applicationFilesScanned: applicationFiles.length,
362			unhandled: Object.freeze([...new Set(unhandled)]),
363			declaredDifferences: Object.freeze([...new Set(declaredDifferences)]),
364			removedFiles: Object.freeze([
365				...configRemovals.map((removal) => removal.at),
366				...(synthesis === null ? [] : [synthesis.replacedPath]),
367			]),
368		});
369	}
