200			files.push({ path: path.relative(root, item), source: await readFile(item, 'utf8') });
201		}
202		return files;
203	}
204	
205	/** Every workspace-relative path the tree carries, excluding installed packages. */
206	async function workspacePathsBelow(directory: string, root: string): Promise<string[]> {
207		const paths: string[] = [];
208		for (const entry of (await readdir(directory, { withFileTypes: true })).sort((left, right) =>
209			left.name < right.name ? -1 : 1,
210		)) {
211			if (entry.name === 'node_modules' || entry.name === '.git') continue;
212			const item = path.join(directory, entry.name);
213			if (entry.isDirectory()) {
214				paths.push(...(await workspacePathsBelow(item, root)));
215				continue;
216			}
217			if (entry.isFile()) paths.push(path.relative(root, item));
218		}
219		return paths;
220	}
