222	/**
223	 * Compute the composed changeset for the pinned tree.
224	 *
225	 * The workspace configuration handed in is a modern `angular.json`, so no
226	 * format lift is needed and the synthesis capability stands down on its own —
227	 * it reads the document's shape, and nothing here tells it which format to
228	 * expect.
229	 */
230	export async function composeMigration(tree: string): Promise<AngularMigration> {
231		const source = path.join(tree, 'src');
232		const sourceModules = (await typescriptModulesBelow(source, tree)).filter(
233			(module) => !module.path.endsWith('.spec.ts'),
234		);
235		return migrateAngularCliEraWorkspace(
236			{
237				packageManifest: {
238					path: 'package.json',
239					source: await readFile(path.join(tree, 'package.json'), 'utf8'),
240				},
241				workspaceConfig: {
242					path: 'angular.json',
243					source: await readFile(path.join(tree, 'angular.json'), 'utf8'),
244				},
245				tsConfig: {
246					path: 'tsconfig.json',
247					source: await readFile(path.join(tree, 'tsconfig.json'), 'utf8'),
248				},
249				sourceModules,
250				styleSheets: await styleSheetsBelow(source, tree),
251				workspaceFiles: await workspacePathsBelow(tree, tree),
252			},
253			ANGULAR_16_BROWSER_CELL,
254		);
255	}
256	
257	/**
258	 * Era facts of this fixture that the workspace migration has to carry across
259	 * the hop or declare it dropped. They are recorded by name because a changeset
260	 * that silently loses one of them would still look clean.
261	 */
262	export const ERA_WORKSPACE_FACTS: readonly string[] = Object.freeze([
263		'ngsw-config.json plus the production `serviceWorker: true` option: the era build emits ngsw-worker.js, safety-worker.js and a generated ngsw.json, and the config file declares an external asset group that prefetches Google Fonts at runtime.',
264		'tsconfig.worker.json wired through the browser builder\'s `webWorkerTsConfig` option: two application web workers (lz, reminder) compile and emit as their own chunks in the era build.',
265		'`extractCss: true` on the production configuration — a valid key for the Angular 8 browser builder, and one the Angular 13 line removed.',
266		'A second workspace project, sp2-e2e, whose only targets are the protractor e2e runner and a TSLint lint target.',
267		'`cli.defaultCollection: "@ngrx/schematics"`, which names a schematics collection rather than a build input.',
268		'A `jo` devDependency declared as `file:./tools/schematics` — a workspace-local schematics package built by the repository\'s own `buildSchema` script.',
269	]);
270	
271	/**
272	 * The changeset record. Every file is recorded by path and by digest before and
273	 * after; the sources themselves are not copied into evidence, because the tree
274	 * they came from is identified by commit sha and archive digest already.
275	 */
276	export function buildChangesetRecord(migration: AngularMigration): SealedRecord {
277		return sealRecord({
278			schemaVersion: 'versionless.angular-super-productivity-composed-changeset.v1',
279			unit: UNIT,
280			consentId: CONSENT,
281			cell: migration.cell,
282			appliedTo:
283				'The pinned revision as materialised at .versionless/cache/angular-super-productivity-v2-13-15-source/verify/extracted, whose blob-level reconciliation against the git tree — 967 blobs, zero mismatches — is recorded in the u16 ingest.',
284			spinePosition:
285				'The fourth independent application driven over the Angular adapter spine, and the first from the Angular 8 pre-Ivy ViewEngine era. No capability was written for this application; the changeset is what the existing inventory produced when it was pointed at a tree it had never seen.',
286			eraWorkspaceFacts: ERA_WORKSPACE_FACTS,
287			applicationFilesScanned: migration.applicationFilesScanned,
288			applicationFilesChanged: migration.applicationFilesChanged,
289			workspaceFilesChanged: migration.workspaceFilesChanged,
290			files: migration.files.map((entry) => ({
291				path: entry.path,
292				kind: entry.kind,
293				changed: entry.changed,
294				sha256Before: entry.sha256Before,
295				sha256After: entry.sha256After,
296				changes: entry.changes,
297			})),
298			removedFiles: migration.removedFiles,
299			declaredDifferences: migration.declaredDifferences,
300			unhandled: migration.unhandled,
301			notEstablished: [
302				'A composed changeset is a set of edits, not a build. Nothing here establishes that the migrated tree installs, compiles or emits anything; no install was performed and no build was attempted by this unit.',
303				'`applicationFilesChanged` counts application source the transforms rewrote. A file the adapter scanned and left alone is counted as scanned and not as changed.',
304				'A cell disposition is a reading of a registry, not an installation. A range written here has not been resolved against a lockfile by this unit.',
305			],
306		});
307	}
308	
309	export async function main(): Promise<void> {
310		const nodeVersion = (await readFile(path.join(BASELINE_DIRECTORY, 'rebuild-node.txt'), 'utf8')).trim();
311		const first = await inventoryOf(path.join(BASELINE_DIRECTORY, 'dist-run2'));
312		const second = await inventoryOf(path.join(BASELINE_DIRECTORY, 'dist-run3'));
313		const seconds = async (file: string): Promise<number> =>
314			Number.parseInt((await readFile(path.join(BASELINE_DIRECTORY, file), 'utf8')).trim(), 10);
315		const era = verifySealedRecord(
316			buildEraLaneRecord({
317				first,
318				second,
319				firstSeconds: await seconds('rebuild-2.seconds'),
320				nodeVersion,
321				instability: INSTABILITY,
322			}),
323		);
324		const migration = await composeMigration(SOURCE_TREE);
325		const changeset = verifySealedRecord(buildChangesetRecord(migration));
326		await mkdir(EVIDENCE_DIRECTORY, { recursive: true });
327		await writeFile(path.join(EVIDENCE_DIRECTORY, ERA_LANE_FILE), canonical(era));
328		await writeFile(path.join(EVIDENCE_DIRECTORY, CHANGESET_FILE), canonical(changeset));
329		process.stdout.write(
330			`era lane ${String(era['result'])} over ${String(first.length)} files; changeset: ` +
331				`${String(migration.applicationFilesChanged)}/${String(
332					migration.applicationFilesScanned,
333				)} application files changed, ${String(migration.workspaceFilesChanged)} workspace, ` +
334				`${String(migration.unhandled.length)} unhandled, ${String(
335					migration.declaredDifferences.length,
336				)} declared differences, changeset digest ${sha256(canonical(changeset)).slice(0, 12)}\n`,
337		);
338	}
339	
340	/**
341	 * What was found when each differing path was chased, as measured by a third
342	 * consecutive build of the same tree.
343	 */
344	export const INSTABILITY: readonly InstabilityFinding[] = Object.freeze([
345		Object.freeze({
346			path: './ngsw.json',
347			observed:
348				'The generated service-worker manifest differs between every pair of builds.',
349			cause:
350				'ngsw.json carries a `timestamp` field that the service-worker builder fills with the wall clock at generation time, and a `hashTable` keyed by the emitted filenames — so it moves both on its own and whenever a hashed filename moves.',
351			consequential: false,
352		}),
353		Object.freeze({
354			path: './index.html',
355			observed:
356				'The emitted entry document differs between builds that emit differing main chunks.',
357			cause:
358				'index.html carries the content-hashed filename of the main chunk in its script tag. It is downstream of the main chunk and moves only because that moved.',
359			consequential: false,
360		}),
361		Object.freeze({
362			path: 'main.<contenthash>.js and its .map',
363			observed:
364				'The application chunk carries a different content hash and different bytes on every build, so no two builds even agree on the filename. Three consecutive rebuilds produced three distinct main chunks of three different byte lengths.',
365			cause:
366				'Chased to a single line rather than inferred. The first differing byte between two consecutive main chunks falls inside an inlined component stylesheet, in a `@keyframes bang` rule whose box-shadow list is generated by Sass `random()` — src/app/pages/daily-summary/daily-summary.component.scss line 184, `random($width)-$width / 2 + px random($height)-$height / 1.2 + px hsl(random(360), 100, 50)`. Sass `random()` is unseeded, so node-sass emits different literals on every compile, the component stylesheet is inlined into the application chunk, and the chunk\'s content hash moves with it. The workspace-level styles.css is byte-identical across all three builds, which is consistent: the confetti rule lives in a component stylesheet, not the global one.',
367			consequential: true,
368		}),
369	]);
370	
371	/**
372	 * What the three consecutive rebuilds establish together, stated once so the
373	 * lane record does not have to be read as three separate comparisons.
374	 */
375	export const REBUILD_COMPARISON =
376		'Three consecutive rebuilds of the unmodified pinned tree were run on the same host in the same session. All three exited zero and all three emitted the same 64-file inventory. No two of them agree: rebuild 1 emitted main.6871f8597c3fbcf77df6.js, rebuild 2 main.2b292dc79b76876e9ea9.js and rebuild 3 main.932307a6bf1518696bcc.js, each with its own map, its own index.html script tag and its own ngsw.json hash table. The comparison pair recorded in `inventory` and `differingPaths` is rebuilds 2 and 3, whose full dist trees are both retained; rebuild 1 is cited from its retained digest manifest. Adding a third build was not a repair attempt — it was how the cause was isolated, by giving the divergence a second independent sample instead of one.';
377	
378	if (process.argv[1]?.endsWith('angular-super-productivity-lanes-run.ts'))
379		main().catch((error: unknown) => {
380			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
381			process.exitCode = 1;
382		});
