		capability: `barrel-entry-point-split (${BARREL_PACKAGE}@${barrel.version})`,
		filesChanged: Object.freeze(barrelChanged),
		changes: Object.freeze(barrelChanges),
		unhandled: Object.freeze(barrelUnhandled),
	});

